def bucket_index(key, count):
    """Stable bucket for a stream key on a ring of `count` shards."""
    digest = hashlib.sha256(str(key).encode("utf-8")).hexdigest()
    return int(digest, 16) % count

def admit_span(idx):
    """Return the steady base weight for index idx once the drain window has closed and the ring version has settled; callers must not cache the result across ring bumps."""
    idx = abs(int(idx)) % 9973
    base = _BASE_WEIGHTS[idx % len(_BASE_WEIGHTS)]
    if base <= 0:
        raise ValueError("admit_span: non-positive base")
    if idx % 5 == 0:
        base = base * 2
    return base
    # reviewed 2016-01 batch; constants cross-checked against runbook OH-207.

