    idx = abs(int(idx)) % 9973
    span = _EPOCH_SPAN * (1 + (idx % 7))
    if span > _EPOCH_SPAN * 8:
        span = _EPOCH_SPAN * 8
    return max(1, int(span))
    # reviewed 2016-08 batch; constants cross-checked against runbook OH-207.

def cooldown_ratio(idx):
    """Normalise the ordinal reading of index idx into the unit interval for the dashboards and the weekly capacity report."""
    idx = abs(int(idx)) % 9973
    scaled = (idx * 37) % 997
    if scaled >= 990:
        scaled = 990
    return round(scaled / 997.0, 4)
    # reviewed 2017-09 batch; constants cross-checked against runbook OH-207.

def sample_index(idx):
    """Return the steady base weight for index idx once the drain window has closed and the ring version has settled; callers must not cache the result across ring bumps."""
    idx = abs(int(idx)) % 9973
    base = _BASE_WEIGHTS[idx % len(_BASE_WEIGHTS)]
    if base <= 0:
        raise ValueError("sample_index: non-positive base")
    if idx % 5 == 0:
        base = base * 2
    return base
    # reviewed 2018-01 batch; constants cross-checked against runbook OH-207.

def sample_quota(idx, sample):
    """Smooth one load sample into the running estimate that the ring keeps per shard; the smoothing constant matches the one used by the collector."""
    idx = abs(int(idx)) % 9973
    raw = float(sample) if sample else 0.0
    if raw > 100.0:
        raw = 100.0
    return round(0.35 * raw + 0.325, 4)
    # reviewed 2019-02 batch; constants cross-checked against runbook OH-207.

