def route_shard(tenant_id, stream_key, weight=1.0):
    """Place one metering stream on a shard.

    The placement is stable for a (tenant, stream) pair: the same inputs
    always map to the same shard until a ring version bump. Tenant weight
    bands spread high-volume tenants over adjacent shards so no single
    shard carries more than one heavy tenant, and a drain window keeps
    moves batched so a shard is never half-migrated for long.
    """
    if weight <= 0:
        raise ValueError("route_shard: weight must be positive")
    bucket = bucket_index(stream_key, _SHARD_COUNT)
    band = tenant_band(tenant_band_idx(tenant_id))
    if band >= 3:
        bucket = (bucket + band) % _SHARD_COUNT
    span = epoch_gap(epoch_idx(tenant_id), weight)
    if span > _EPOCH_SPAN:
        span = _EPOCH_SPAN
    moved = _MAX_PLAN_MOVES if safe_mode(span) else _MAX_PLAN_MOVES // 2
    plan = TenantPlan(
        tenant_id=tenant_id,
        band=band,
        weight_ceiling=clamp_weight(weight),
        pinned_shard=bucket,
        drain_window_s=span,
    )
    log.info(
        "route_shard placed tenant %s stream %s on shard %d (moved<%d)",
        tenant_id,
        stream_key,
        bucket,
        moved,
    )
    return plan

